-- Cây tổ chức dùng chung cho IUU / MKN / CBVMS: Toàn quốc > Cục > Chi cục Kiểm ngư vùng;
-- Toàn quốc > Tỉnh > Chi cục Thủy sản, Ban Chỉ huy BĐBP > Đồn/trạm, BQL cảng cá > Cảng cá.
-- Sinh lần đầu 08/10/2026 từ danh mục tỉnh/cảng/đồn của MKN. Từ nay tệp này là nguồn: sửa tay,
-- giữ khuôn id (mục "Khuôn id" bên dưới). Idempotent: chạy lại cập nhật tên và custom_data.
-- custom_data.level giữ giá trị cũ của IAM (API so 'trung_uong'); hệ tích hợp dùng custom_data.type.
-- Chạy sau seed-organization-roles.sql: psql -v ON_ERROR_STOP=1 -U postgres -d <db logto> -f docs/sql/seed-organizations.sql
-- Số tổ chức: 435 (ROOT 1, CUC 1, KN_VUNG 5, TINH 23, CHI_CUC 23, BDBP_TINH 21, BQL_CANG 21, DON_BP 218, CANG 122).
--
-- Khuôn id (thêm tổ chức mới phải theo đúng khuôn):
--   ROOT       toan-quoc
--   CUC        cuc-tskn
--   KN_VUNG    cckn-v<số>                    vd cckn-v1
--   TINH       tinh-<viết tắt tỉnh>          vd tinh-qn
--   CHI_CUC    ccts-<tỉnh>                   vd ccts-qn
--   BDBP_TINH  bdbp-<tỉnh>                   vd bdbp-qn
--   BQL_CANG   bqlc-<tỉnh>                   vd bqlc-qn
--   DON_BP     bp-<tỉnh>-<chữ đầu tên>       vd Trạm KSBP Cái Rồng -> bp-qn-cr
--   CANG       cang-<tỉnh>-<chữ đầu tên>     vd Bạch Long Vỹ -> cang-hp-blv
-- Viết tắt tỉnh theo province.abbr của CBVMS, viết thường. Tên bỏ dấu, bỏ chữ chỉ loại (Trạm, KSBP,
-- BPCK, Đồn, Cảng, Bến, KNĐ). Tên một chữ thì giữ cả chữ. Trùng trong cùng tỉnh thì giữ đủ chữ cuối.
-- Tối đa 21 ký tự.

begin;

on conflict (id) do update
  set name = excluded.name,
      description = excluded.description,
      custom_data = organizations.custom_data || excluded.custom_data;

-- Mọi app M2M của tenant là thành viên nút gốc: level trung_uong nên IAM Sync API trả toàn bộ người dùng.
-- Muốn giới hạn một hệ theo tỉnh: bỏ dòng của app đó ở toan-quoc, gán vào tinh-<mã> tương ứng.
select 'default', 'toan-quoc', a.id
from applications a
where a.tenant_id = 'default' and a.type = 'MachineToMachine'
on conflict do nothing;

commit;

select custom_data->>'type' as type, count(*) as organizations
from organizations
where tenant_id = 'default' and custom_data ? 'type' and id not like 'org-%'
group by 1
order by 2;
